package glitch

import data.glitch_lib

# Set of strings that indicate excessive privilege or administrative access patterns
admin_patterns := {"administrator", "admin", "root", "owner", "superuser", "allaccess", "fullaccess", "privileged"}

# Set of strings that indicate wildcard permissions
wildcard_patterns := {"*", "all", "allusers", "allauthenticatedusers"}

# Check if a string value contains administrative or wildcard patterns
check_excessive_privilege(value) {
    value.ir_type == "String"
    some pattern in admin_patterns
    regex.match(sprintf("(?i).*%s.*", [pattern]), value.value)
} else {
    value.ir_type == "String"
    some pattern in wildcard_patterns
    regex.match(sprintf("(?i).*%s.*", [pattern]), value.value)
}

# Check for privileged boolean flag
check_privileged_flag(value) {
    value.ir_type == "Boolean"
    value.value == true
}

# Check for runAsUser root (UID 0)
check_run_as_root(value) {
    value.ir_type == "Integer"
    value.value == 0
} else {
    value.ir_type == "String"
    regex.match("^0$", value.value)
}

# Rule for Service Account & IAM Principal Privilege Escalation
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Look for IAM role bindings or service account configurations
    node.type in {"iam_binding", "service_account", "role", "principal"}

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for excessive permissions in role or scopes
    attr.name in {"role", "scopes", "policy", "attach_policy_arn"}
    check_excessive_privilege(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Excessive privilege assigned to service account or IAM principal - CWE-250: Execution with Unnecessary Privileges"
    }
}

# Rule for Container Runtime Privilege Escalation
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Look for container or pod security configurations
    node.type in {"container", "pod", "security_context"}

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for privileged mode or runAsUser root
    attr.name in {"privileged", "runAsUser", "runAsRoot"}
    check_privileged_flag(attr.value) or check_run_as_root(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Container running with excessive privileges - CWE-250: Execution with Unnecessary Privileges"
    }
}

# Rule for Operating System Execution Context
Glitch_Analysis[result] {
